package com.bank.txnmonitor;

import java.util.*;
import java.util.logging.*;
import java.util.stream.IntStream;

public class CountDemo {
    private static final Logger log = Logger.getLogger("TxnMonitor");
    static {
        ConsoleHandler h = new ConsoleHandler();
        h.setFormatter(new SimpleFormatter());
        log.setUseParentHandlers(false);
        log.addHandler(h);
    }

    public static void main(String[] args) {
        List<Integer> txns = IntStream.rangeClosed(1, 1000).boxed().toList();
        TxnMonitorService service = new TxnMonitorService();

        log.info(() -> "count()           : " + service.highValueCount(txns));
        log.info(() -> "collect().size()  : " + service.highValueCountWasteful(txns));
    }
}

// ─── Would be in service/TxnMonitorService.java ───
class TxnMonitorService {
    // efficient: just tally, no list allocated
    long highValueCount(List<Integer> txns) {
        return txns.stream().filter(n -> n > 500).count();
    }
    // wasteful: builds a full list only to read its size
    long highValueCountWasteful(List<Integer> txns) {
        return txns.stream().filter(n -> n > 500)
            .collect(java.util.stream.Collectors.toList()).size();  // discarded list!
    }
}
